#!/usr/bin/env bash
# update_project-09-privacy-policy-sync.sh  (WayArs)
# 1) AndroidManifest: allowBackup="false"  (policy says data stays local, not in cloud backup)
# 2) In-app Privacy Policy text (settings_privacy_content) synced with the website
#    https://apstudiomobile.pl/wayars/privacy/  (last updated: October 5, 2026)
#    - en / pl / ru / uk: full translated text
#    - other languages: current English text (so no screen shows an outdated policy)
# Idempotent: safe to run twice.  Run BEFORE git add/commit/push.
set -e
cd "$(dirname "$0")"
[ -f app/src/main/AndroidManifest.xml ] || { echo "Run this script from the WayArs repo root"; exit 1; }

python3 - <<'PYEOF2'
import json, re, glob, os
MANIFEST = "app/src/main/AndroidManifest.xml"
DATA = json.loads(r'''{"en": "\"**WayArs Privacy Policy**\\nLast updated: October 5, 2026\\n\\n**Protecting your privacy**\\nWe respect your privacy. WayArs is developed and operated by Arsenii Panicev (AP STUDIO), an independent developer. WayArs is designed around Privacy by Design — the core screen-analysis and rate-calculation operations run locally on your device.\\n\\n**Data collection and use**\\n• Accessibility Service: the app uses this access exclusively to read order details (e.g. price, distance) shown on screen by the supported delivery and taxi apps (built in and added by you) in order to calculate order profitability. The app does not record passwords, personal data or keystrokes. Data read through the service is processed locally on your device, is not sent to external servers, and is not shared with third parties or used for advertising.\\n• Notifications (Notification Listener): notification access is used only to detect new order offers while the app runs in the background.\\n• Order history: for the statistics screen the app saves, on your device only, the amount, currency, distance, time, calculated rates and verdict of each evaluated order and whether you accepted it. It contains no addresses, names or other personal details and is never sent anywhere.\\n• Vehicle and rate data: data you enter in Settings (fuel consumption, fuel price, evaluation thresholds) is stored only in local device storage.\\n• Installed apps list: when you add an app to scan, the app shows the launchable apps installed on your device. The list is not stored or sent anywhere; only the apps you choose are saved locally.\\n• Floating overlay: the “display over other apps” permission is used only to show the order verdict card above the delivery or taxi app. No data is collected through it.\\n• App updates: the app asks Google Play whether a newer version is available (Google Play in-app updates API).\\n\\n**Subscriptions and third-party providers**\\nThe app offers features on a subscription basis. The app does not collect or store detailed payment data (such as credit card numbers). To process transactions and verify subscription status, we rely on trusted third-party providers:\\n• Google Play Billing (Google LLC): payments and transactions are handled directly by the Google Play Store. Policy: policies.google.com/privacy\\n• RevenueCat, Inc.: subscription status verification based on anonymous device and transaction identifiers. Policy: revenuecat.com/privacy\\n\\n**Children’s privacy**\\nWayArs is intended solely for adults who are legally permitted to work as a driver or courier. The app is not directed at children under 16 and does not knowingly collect or process any personal data from children. If you become aware that a child has provided us with any data, please contact us at apstudiomobile@gmail.com so we can take appropriate action promptly.\\n\\n**Managing permissions and your subscription**\\nYou can revoke granted permissions at any time in Android system settings, or manage and cancel your subscription directly in your Google Play account settings.\\n\\n**Data deletion and retention**\\nWayArs has no user accounts, and we do not operate our own servers that store your personal data. Data entered in the app is stored locally on your device and can be deleted at any time by clearing the app data (Android Settings → Apps → WayArs → Storage → Clear data) or by uninstalling the app. The app does not use Android automatic cloud backup, so your local data is not copied to your Google account. To request deletion of technical subscription identifiers processed by RevenueCat, contact us at apstudiomobile@gmail.com.\\n\\n**Contact**\\nDeveloper: AP STUDIO (Arsenii Panicev)\\napstudiomobile@gmail.com\"", "pl": "\"**Polityka Prywatności Aplikacji WayArs**\\nData ostatniej aktualizacji: 5 października 2026 r.\\n\\n**Ochrona prywatności**\\nSzanujemy Twoją prywatność. Aplikacja WayArs jest tworzona i prowadzona przez Arsenii Panicev (AP STUDIO), niezależnego twórcę („my”). WayArs został zaprojektowany zgodnie z zasadą Privacy by Design — kluczowe operacje analizy ekranu i obliczania stawek wykonywane są lokalnie na Twoim urządzeniu.\\n\\n**Gromadzenie i wykorzystanie danych**\\n• Usługa dostępności: Aplikacja korzysta z tego dostępu wyłącznie do odczytu parametrów zleceń (np. kwoty, odległości) wyświetlanych na ekranie w obsługiwanych aplikacjach dostaw i taxi (wbudowanych oraz dodanych przez użytkownika), aby obliczać opłacalność zlecenia. Aplikacja nie rejestruje haseł, danych osobowych ani naciśnięć klawiszy. Dane odczytywane przez usługę dostępności są przetwarzane lokalnie na Twoim urządzeniu, nie są wysyłane na zewnętrzne serwery, nie są udostępniane osobom trzecim ani wykorzystywane do reklam.\\n• Powiadomienia: Dostęp do powiadomień służy wyłącznie do wykrywania nowych propozycji zleceń, gdy aplikacja działa w tle.\\n• Historia zleceń: Na potrzeby ekranu statystyk aplikacja zapisuje wyłącznie na Twoim urządzeniu kwotę, walutę, odległość, czas, obliczone stawki i ocenę każdego ocenionego zlecenia oraz informację, czy je zaakceptowałeś. Nie zawiera ona adresów, imion ani innych danych osobowych i nigdy nie jest nigdzie wysyłana.\\n• Dane pojazdu i stawek: Dane wprowadzone w ustawieniach (zużycie paliwa, cena paliwa, progi oceny) są przechowywane wyłącznie w pamięci lokalnej urządzenia.\\n• Lista zainstalowanych aplikacji: Gdy dodajesz aplikację do skanowania, aplikacja pokazuje listę uruchamialnych aplikacji zainstalowanych na urządzeniu. Lista nie jest zapisywana ani nigdzie wysyłana; lokalnie zapisywane są tylko wybrane przez Ciebie aplikacje.\\n• Pływająca nakładka: Uprawnienie „wyświetlanie nad innymi aplikacjami” służy wyłącznie do pokazania karty z oceną zlecenia nad aplikacją dostaw lub taxi. Za jego pomocą nie są zbierane żadne dane.\\n• Aktualizacje aplikacji: Aplikacja pyta Google Play, czy dostępna jest nowsza wersja (API aktualizacji w aplikacji Google Play).\\n\\n**Subskrypcje i dostawcy zewnętrzni**\\nAplikacja oferuje funkcje w modelu subskrypcji. Aplikacja nie zbiera ani nie przechowuje szczegółowych danych płatniczych (np. numerów kart bankowych). Do obsługi transakcji i weryfikacji statusu subskrypcji korzystamy z zaufanych dostawców zewnętrznych:\\n• Google Play Billing (Google LLC): Płatności i transakcje są obsługiwane bezpośrednio przez Sklep Google Play.\\n• RevenueCat, Inc.: Weryfikacja subskrypcji na podstawie anonimowych identyfikatorów urządzenia i transakcji.\\n\\n**Prywatność dzieci**\\nWayArs jest przeznaczony wyłącznie dla dorosłych uprawnionych do pracy jako kierowca lub kurier. Aplikacja nie jest skierowana do dzieci poniżej 16 roku życia i nie gromadzi ani nie przetwarza świadomie danych osobowych dzieci. Jeśli dowiesz się, że dziecko przekazało nam jakiekolwiek dane, skontaktuj się z nami pod adresem apstudiomobile@gmail.com, abyśmy mogli niezwłocznie podjąć odpowiednie działania.\\n\\n**Zarządzanie uprawnieniami i subskrypcją**\\nPrzyznane uprawnienia możesz w każdej chwili cofnąć w ustawieniach systemu Android, a subskrypcją zarządzać i anulować ją bezpośrednio w ustawieniach konta Google Play.\\n\\n**Usuwanie i przechowywanie danych**\\nWayArs nie posiada kont użytkowników, a my nie prowadzimy własnych serwerów przechowujących Twoje dane osobowe. Dane wprowadzone w aplikacji są przechowywane lokalnie na Twoim urządzeniu i możesz je w każdej chwili usunąć, czyszcząc dane aplikacji (Ustawienia Android → Aplikacje → WayArs → Pamięć → Wyczyść dane) lub odinstalowując aplikację. Aplikacja nie korzysta z automatycznej kopii zapasowej Android w chmurze, więc Twoje dane lokalne nie są kopiowane na Twoje konto Google. Aby poprosić o usunięcie technicznych identyfikatorów subskrypcji przetwarzanych przez RevenueCat, napisz do nas pod adres apstudiomobile@gmail.com.\\n\\n**Kontakt**\\nTwórca: AP STUDIO (Arsenii Panicev)\\napstudiomobile@gmail.com\"", "ru": "\"**Политика конфиденциальности приложения WayArs**\\nПоследнее обновление: 5 октября 2026 г.\\n\\n**Защита конфиденциальности**\\nМы уважаем вашу конфиденциальность. Приложение WayArs разрабатывает и поддерживает Arsenii Panicev (AP STUDIO), независимый разработчик («мы»). WayArs создан по принципам Privacy by Design — ключевые операции анализа экрана и расчёта тарифов выполняются локально на вашем устройстве.\\n\\n**Сбор и использование данных**\\n• Служба специальных возможностей: Приложение использует этот доступ исключительно для чтения параметров заказов (например, суммы, расстояния), отображаемых на экране в поддерживаемых приложениях доставки и такси (встроенных и добавленных пользователем), чтобы рассчитывать выгодность заказа. Приложение не записывает пароли, персональные данные и нажатия клавиш. Данные, считанные через службу специальных возможностей, обрабатываются локально на вашем устройстве, не отправляются на внешние серверы, не передаются третьим лицам и не используются для рекламы.\\n• Уведомления: Доступ к уведомлениям используется только для обнаружения новых предложений заказов, пока приложение работает в фоновом режиме.\\n• История заказов: Для экрана статистики приложение сохраняет только на вашем устройстве сумму, валюту, расстояние, время, рассчитанные тарифы и вердикт по каждому оценённому заказу, а также отметку, приняли ли вы его. В ней нет адресов, имён и других персональных данных, и она никуда не отправляется.\\n• Данные автомобиля и тарифов: Данные, введённые в настройках (расход топлива, цена топлива, пороги оценки), хранятся только в локальной памяти устройства.\\n• Список установленных приложений: Когда вы добавляете приложение для сканирования, приложение показывает список запускаемых приложений, установленных на устройстве. Список не сохраняется и никуда не отправляется; локально сохраняются только выбранные вами приложения.\\n• Плавающее окно: Разрешение «поверх других приложений» используется только для показа карточки с вердиктом по заказу поверх приложения доставки или такси. Через него никакие данные не собираются.\\n• Обновления приложения: Приложение запрашивает у Google Play, доступна ли новая версия (API обновлений внутри приложения Google Play).\\n\\n**Подписки и сторонние поставщики**\\nПриложение предлагает функции по подписке. Приложение не собирает и не хранит подробные платёжные данные (например, номера банковских карт). Для обработки транзакций и проверки статуса подписки мы используем надёжных сторонних поставщиков:\\n• Google Play Billing (Google LLC): Обработку платежей и транзакций выполняет непосредственно магазин Google Play.\\n• RevenueCat, Inc.: Проверка подписки на основе анонимных идентификаторов устройства и транзакций.\\n\\n**Конфиденциальность детей**\\nWayArs предназначен исключительно для взрослых, имеющих право работать водителем или курьером. Приложение не ориентировано на детей младше 16 лет и сознательно не собирает и не обрабатывает персональные данные детей. Если вам станет известно, что ребёнок передал нам какие-либо данные, свяжитесь с нами по адресу apstudiomobile@gmail.com, чтобы мы могли оперативно принять необходимые меры.\\n\\n**Управление разрешениями и подпиской**\\nВы можете в любой момент отозвать выданные разрешения в настройках Android, а также управлять подпиской и отменить её в настройках аккаунта Google Play.\\n\\n**Удаление и хранение данных**\\nВ WayArs нет учётных записей пользователей, и мы не используем собственные серверы для хранения ваших персональных данных. Данные, введённые в приложении, хранятся локально на вашем устройстве, и вы можете удалить их в любой момент, очистив данные приложения (Настройки Android → Приложения → WayArs → Хранилище → Очистить данные) или удалив приложение. Приложение не использует автоматическое облачное резервное копирование Android, поэтому ваши локальные данные не копируются в ваш аккаунт Google. Чтобы запросить удаление технических идентификаторов подписки, обрабатываемых RevenueCat, напишите нам по адресу apstudiomobile@gmail.com.\\n\\n**Контакты**\\nРазработчик: AP STUDIO (Arsenii Panicev)\\napstudiomobile@gmail.com\"", "uk": "\"**Політика конфіденційності застосунку WayArs**\\nОстаннє оновлення: 5 жовтня 2026 р.\\n\\n**Захист конфіденційності**\\nМи поважаємо вашу конфіденційність. Застосунок WayArs розробляє та підтримує Arsenii Panicev (AP STUDIO), незалежний розробник («ми»). WayArs створено за принципами Privacy by Design — ключові операції аналізу екрана та розрахунку тарифів виконуються локально на вашому пристрої.\\n\\n**Збір і використання даних**\\n• Служба спеціальних можливостей: Застосунок використовує цей доступ виключно для читання параметрів замовлень (наприклад, суми, відстані), що відображаються на екрані в підтримуваних застосунках доставки й таксі (вбудованих і доданих користувачем), щоб розраховувати вигідність замовлення. Застосунок не записує паролі, персональні дані та натискання клавіш. Дані, зчитані через службу спеціальних можливостей, обробляються локально на вашому пристрої, не надсилаються на зовнішні сервери, не передаються третім особам і не використовуються для реклами.\\n• Сповіщення: Доступ до сповіщень використовується лише для виявлення нових пропозицій замовлень, поки застосунок працює у фоновому режимі.\\n• Історія замовлень: Для екрана статистики застосунок зберігає лише на вашому пристрої суму, валюту, відстань, час, розраховані тарифи та вердикт щодо кожного оціненого замовлення, а також позначку, чи ви його прийняли. У ній немає адрес, імен та інших персональних даних, і вона ніколи нікуди не надсилається.\\n• Дані автомобіля та тарифів: Дані, введені в налаштуваннях (витрата пального, ціна пального, пороги оцінювання), зберігаються лише в локальній пам’яті пристрою.\\n• Список встановлених застосунків: Коли ви додаєте застосунок для сканування, застосунок показує список застосунків, що запускаються і встановлені на пристрої. Список не зберігається й нікуди не надсилається; локально зберігаються лише обрані вами застосунки.\\n• Плаваюче вікно: Дозвіл «поверх інших застосунків» використовується лише для показу картки з вердиктом щодо замовлення поверх застосунку доставки або таксі. Через нього жодні дані не збираються.\\n• Оновлення застосунку: Застосунок запитує в Google Play, чи доступна нова версія (API оновлень усередині застосунку Google Play).\\n\\n**Підписки та сторонні постачальники**\\nЗастосунок пропонує функції за підпискою. Застосунок не збирає і не зберігає детальні платіжні дані (наприклад, номери банківських карток). Для обробки транзакцій і перевірки статусу підписки ми користуємося надійними сторонніми постачальниками:\\n• Google Play Billing (Google LLC): Обробку платежів і транзакцій виконує безпосередньо магазин Google Play.\\n• RevenueCat, Inc.: Перевірка підписки на основі анонімних ідентифікаторів пристрою та транзакцій.\\n\\n**Конфіденційність дітей**\\nWayArs призначений виключно для дорослих, які мають право працювати водієм або кур’єром. Застосунок не орієнтований на дітей віком до 16 років і свідомо не збирає та не обробляє персональні дані дітей. Якщо вам стане відомо, що дитина передала нам будь-які дані, зв’яжіться з нами за адресою apstudiomobile@gmail.com, щоб ми могли негайно вжити відповідних заходів.\\n\\n**Керування дозволами та підпискою**\\nВи можете в будь-який момент скасувати надані дозволи в налаштуваннях Android, а також керувати підпискою та скасувати її в налаштуваннях облікового запису Google Play.\\n\\n**Видалення та зберігання даних**\\nУ WayArs немає облікових записів користувачів, і ми не використовуємо власні сервери для зберігання ваших персональних даних. Дані, введені в застосунку, зберігаються локально на вашому пристрої, і ви можете видалити їх у будь-який момент, очистивши дані застосунку (Налаштування Android → Застосунки → WayArs → Сховище → Очистити дані) або видаливши застосунок. Застосунок не використовує автоматичне хмарне резервне копіювання Android, тож ваші локальні дані не копіюються до вашого облікового запису Google. Щоб запросити видалення технічних ідентифікаторів підписки, які обробляє RevenueCat, напишіть нам за адресою apstudiomobile@gmail.com.\\n\\n**Контакти**\\nРозробник: AP STUDIO (Arsenii Panicev)\\napstudiomobile@gmail.com\""}''')

# --- 1) manifest
m = open(MANIFEST, encoding="utf-8").read()
if 'android:allowBackup="true"' in m:
    m = m.replace('android:allowBackup="true"', 'android:allowBackup="false"')
    open(MANIFEST, "w", encoding="utf-8").write(m)
    print("manifest: allowBackup -> false")
else:
    print("manifest: already OK")

# --- 2) strings
pat = re.compile(r'(<string name="settings_privacy_content">)(.*?)(</string>)', re.S)
changed = 0
for f in sorted(glob.glob("app/src/main/res/values*/strings.xml")):
    d = os.path.basename(os.path.dirname(f))
    lang = d.split("-")[1] if "-" in d else "en"
    new = DATA.get(lang, DATA["en"])
    s = open(f, encoding="utf-8").read()
    if not pat.search(s):
        continue
    out = pat.sub(lambda mo: mo.group(1) + new + mo.group(3), s, count=1)
    if out != s:
        open(f, "w", encoding="utf-8").write(out)
        changed += 1
        print("updated", f, "(" + (lang if lang in DATA else "en text") + ")")
print("files changed:", changed)
PYEOF2
echo "Done. Now: git add -A && git commit -m 'Privacy policy sync, allowBackup=false' && git push"
